<?php
/** Read-only object-cache capability and isolated round-trip check. @package NakhostinPerformanceEngine */
namespace Nakhostin\PerformanceEngine\Diagnostics;
final class ObjectCacheHealthCheck {
	public function run(): array { $persistent = function_exists( 'wp_using_ext_object_cache' ) && wp_using_ext_object_cache(); $redis = class_exists( 'Redis' ) || defined( 'WP_REDIS_HOST' ); $memcached = class_exists( 'Memcached' ) || class_exists( 'Memcache' ); $backend = $redis ? 'redis' : ( $memcached ? 'memcached' : ( $persistent ? 'external' : 'runtime' ) ); $roundtrip = null; if ( function_exists( 'wp_cache_set' ) && function_exists( 'wp_cache_get' ) && function_exists( 'wp_cache_delete' ) ) { $random = function_exists( 'wp_rand' ) ? wp_rand() : random_int( 1, PHP_INT_MAX ); $key = 'health-' . substr( hash( 'sha256', microtime( true ) . $random ), 0, 12 ); $value = function_exists( 'wp_rand' ) ? wp_rand() : random_int( 1, PHP_INT_MAX ); $set = wp_cache_set( $key, $value, 'npe-health', 30 ); $get = wp_cache_get( $key, 'npe-health' ); $delete = wp_cache_delete( $key, 'npe-health' ); $roundtrip = $set && $get === $value && $delete; } return array( 'persistent' => (bool) $persistent, 'backend' => $backend, 'redis_extension' => $redis, 'redis_dropin' => $persistent && 'redis' === $backend, 'memcached_available' => $memcached, 'roundtrip' => $roundtrip, 'recommendation' => $redis && ! $persistent ? 'Redis is available to PHP but WordPress is not using persistent object caching.' : '' ); }
}
